class Ticket {
    // 모든 표가 함께 읽는 클래스 변수예요.
    static int total = 4;
}

public class Main {
    public static void main(String[] args) {
        System.out.println(Ticket.total);
    }
}

class Ticket {
    static int total;
    // local은 각 객체에 따로 있어요.
    int local;
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        a.local++;
        Ticket.total++;
        System.out.println(a.local + ":" + b.local + ":" + Ticket.total);
    }
}

class Ticket {
    static int total;
    // new로 만들 때마다 생성자를 실행해요.
    Ticket() { total++; }
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = a;
        System.out.println(Ticket.total);
    }
}

class Ticket {
    // read를 부를 때 b는 아직 기본값0이에요.
    static int a = read();
    static int b = 7;
    static int read() { return b; }
}

public class Main {
    public static void main(String[] args) {
        System.out.println(Ticket.a + ":" + Ticket.b);
    }
}

class Ticket {
    static { System.out.print("S"); }
    { System.out.print("I"); }
    Ticket() { System.out.print("C"); }
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        System.out.println();
    }
}

class Parent {
    static { System.out.print("P"); }
    { System.out.print("p"); }
    Parent() { System.out.print("1"); }
}
class Ticket extends Parent {
    static { System.out.print("C"); }
    { System.out.print("c"); }
    Ticket() { System.out.print("2"); }
}

public class Main {
    public static void main(String[] args) {
        new Ticket();
        System.out.println();
    }
}

class Ticket {
    static int total;
    int local;
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        a.total += 2;
        System.out.println(b.total + ":" + b.local);
    }
}

class Ticket {
    static int next = 1;
    // 객체마다 먼저 번호를 받아요.
    int id = next++;
    // 필드 초기화 다음에 생성자를 실행해요.
    Ticket() { next += 10; }
}

public class Main {
    public static void main(String[] args) {
        Ticket a = new Ticket();
        Ticket b = new Ticket();
        System.out.println(a.id + ":" + b.id + ":" + Ticket.next);
    }
}
